#include "adcs/control.hpp"
#include "adcs/mode.hpp"
#include "adcs/flight.hpp"
#include <gtest/gtest.h>
TEST(Control,PdLqrAndAllocation){const adcs::Quat i{1,0,0,0},x90{std::sqrt(.5),std::sqrt(.5),0,0};EXPECT_GT(adcs::quaternion_pd(x90,i,adcs::Vec3::Zero(),adcs::Vec3::Ones(),adcs::Vec3::Ones())(0),0);adcs::Matrix3x6 g=adcs::Matrix3x6::Zero();g(0,0)=g(1,1)=g(2,2)=.0005;EXPECT_GT(adcs::quaternion_lqr(x90,i,adcs::Vec3::Zero(),g)(0),0);Eigen::Matrix3d a=Eigen::Matrix3d::Identity();const adcs::Vec3 c{1e-4,-2e-4,3e-4};EXPECT_LT((-a*adcs::allocate_wheel_torque<3>(c,a)-c).norm(),1e-15);}
TEST(Modes,ReferenceSequence){adcs::ModeState x;adcs::ModeStatus s;s.initialization_complete=true;s.body_rate=.1;adcs::update_mode(x,s);EXPECT_EQ(x.mode,adcs::Mode::detumble);s.body_rate=.001;adcs::update_mode(x,s);EXPECT_EQ(x.mode,adcs::Mode::safe);s.nominal_requested=true;adcs::update_mode(x,s);EXPECT_EQ(x.mode,adcs::Mode::nominal);s.wheel_speed_fraction=.9;adcs::update_mode(x,s);EXPECT_EQ(x.mode,adcs::Mode::desaturation);s.fault=true;adcs::update_mode(x,s);EXPECT_EQ(x.mode,adcs::Mode::fault);EXPECT_FALSE(adcs::mode_command(adcs::Mode::fault).reaction_wheels);}
TEST(FlightApi,DeterministicEstimateToActuatorBoundary){adcs::FlightComputer flight;flight.predict_gyro({0,0,.01},.01);adcs::ModeStatus status;status.initialization_complete=true;flight.update_mode_state(status);const auto output=flight.control({{std::sqrt(.5),std::sqrt(.5),0,0}},adcs::Vec3::Zero(),adcs::FeedbackLaw::pd);EXPECT_EQ(output.mode,adcs::Mode::safe);EXPECT_LE(output.wheel_motor_torque_nm.cwiseAbs().maxCoeff(),2e-4);EXPECT_GT(output.requested_body_torque_nm(0),0);}
